const body = $json.body || $json;

const message = body.message || body.prompt || 'Say hello from Agentics.';
const model = body.model || 'agentics-assistant:latest';

const payload = {
  model,
  prompt: message,
  stream: false,
  options: {
    temperature: Number(body.temperature || 0.4),
    num_ctx: Number(body.num_ctx || 4096),
    num_predict: Number(body.num_predict || 512)
  }
};

const res = await fetch('http://ollama:11434/api/generate', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(payload)
});

const text = await res.text();

if (!res.ok) {
  return [{ json: { ok: false, status: res.status, error: text } }];
}

const data = JSON.parse(text);

return [{
  json: {
    ok: true,
    source: 'n8n-agentics-chat-v2',
    model: data.model,
    response: data.response,
    eval_count: data.eval_count,
    total_duration: data.total_duration
  }
}];
